#!/usr/bin/env python3
"""Versioned 1.0.26 update: bounded streamed workflow generation and saved-review reuse."""
import argparse
import base64
import datetime as dt
import fcntl
import hashlib
import json
import os
from pathlib import Path
import shutil
import subprocess
import sys
import urllib.request
import zlib

# Exact accepted package baselines; content hashes are checked before mutation.
DATA = json.loads(zlib.decompress(base64.b64decode('')))

VERSION = '1.0.26'
EVALUATION_HASH = 'b5ffd242d8256902e309bbe816e631da4c932e93c324a85a1a6edc36af6aa8d4'
PROJECT_ID = 'jt-261013-a79fce'


def stop(code, message):
    raise RuntimeError('STOP '+code+' / '+message)


def sha(value):
    return hashlib.sha256(value if isinstance(value, bytes) else json.dumps(value, sort_keys=True, ensure_ascii=False, separators=(',', ':')).encode()).hexdigest()


def load(path):
    return json.loads(path.read_text())


def save(path, value):
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary = path.with_name(path.name+'.upgrade-tmp')
    temporary.write_text(json.dumps(value, ensure_ascii=False, indent=2)+'\n')
    temporary.chmod(0o600)
    os.replace(temporary, path)


def target(root, name):
    relative = Path(name)
    if relative.is_absolute() or '..' in relative.parts or not relative.parts or relative.parts[0] == '.jt':
        stop('PAYLOAD_INVALID', '不正な更新先です。')
    path = root/relative
    if path.is_symlink() or any(parent.is_symlink() for parent in path.parents if parent != root.parent):
        stop('PACKAGE_CHANGED', 'シンボリックリンクの更新先です: '+name)
    return path


def payload():
    if not DATA:
        stop('RELEASE_NOT_PACKAGED', '最終ファイル照合前の準備版です。実行用リリースではありません。')
    baselines = DATA.get('baselines', {})
    if set(baselines) != {'1.0.25'} or any(v.get('version') != k for k, v in baselines.items()) or DATA['new']['version'] != VERSION:
        stop('PAYLOAD_INVALID', '更新元・更新先の版が不正です。')
    decoded = {name: base64.b64decode(value, validate=True) for name, value in DATA['files'].items()}
    if json.loads(decoded['package-manifest.json']) != DATA['new']:
        stop('PAYLOAD_INVALID', '更新先マニフェストが一致しません。')
    for name, content in decoded.items():
        if name != 'package-manifest.json' and sha(content) != DATA['new']['files'].get(name):
            stop('PAYLOAD_INVALID', '更新ファイルのハッシュが一致しません: '+name)
    expected = {name for baseline in baselines.values() for name, digest in DATA['new']['files'].items() if baseline['files'].get(name) != digest}
    if set(decoded) != expected | {'package-manifest.json'}:
        stop('PAYLOAD_INVALID', '更新差分が一致しません。')
    if any(set(baseline['files']) - set(DATA['new']['files']) for baseline in baselines.values()):
        stop('PAYLOAD_INVALID', '既存ファイルを削除する更新は許可されていません。')
    return decoded


def verify_package(root, current, progress):
    baselines = DATA['baselines']
    resumable = progress is not None and progress.get('payload_hash') == sha(DATA)
    if progress:
        baseline = baselines.get(progress.get('from_version'))
        if not resumable or baseline is None or progress.get('baseline_hash') != sha(baseline) or progress.get('phase') not in ('PREPARED', 'INSTALLED', 'DEPLOYED'):
            stop('UPDATE_CONFLICT', '別の更新記録、または不明な更新元があります。')
    else:
        baseline = baselines.get(current.get('version'))
        if baseline is None or current != baseline:
            stop('PACKAGE_CHANGED', 'この更新は確認済みの1.0.25環境を対象とします。')
    if current != baseline and not (resumable and current == DATA['new']):
        stop('UPDATE_CONFLICT', '更新記録と更新元のマニフェストが一致しません。')
    for name, original in baseline['files'].items():
        path = target(root, name)
        allowed = {original}
        if resumable:
            allowed.add(DATA['new']['files'][name])
        if not path.is_file() or sha(path.read_bytes()) not in allowed:
            stop('PACKAGE_CHANGED', '未確認の変更: '+name)
    for name in set(DATA['new']['files']) - set(baseline['files']):
        path = target(root, name)
        if path.exists() and (not resumable or not path.is_file() or sha(path.read_bytes()) != DATA['new']['files'][name]):
            stop('PACKAGE_CHANGED', '新規ファイルが衝突: '+name)
    if progress and progress.get('phase') in ('INSTALLED', 'DEPLOYED'):
        if current != DATA['new']:
            stop('UPDATE_CONFLICT', '更新記録とマニフェストが一致しません。')
        for name, expected in DATA['new']['files'].items():
            path = target(root, name)
            if not path.is_file() or sha(path.read_bytes()) != expected:
                stop('PACKAGE_CHANGED', '適用済みファイルが変化しています: '+name)
    return baseline


def local_snapshot(private):
    excluded = {'state.json', 'config.json', 'runbook.lock'}
    return {str(p.relative_to(private)): sha(p.read_bytes()) for p in private.rglob('*')
            if p.is_file() and p.relative_to(private).as_posix() not in excluded
            and not p.relative_to(private).as_posix().startswith('upgrades/'+VERSION+'/')}


def verify_local_records(root, progress):
    private = root/'.jt'
    before, after = progress['original_state'], load(private/'state.json')
    for name, value in before.items():
        if name == 'package_version':
            continue
        if name in ('actions', 'upgrades'):
            if any(after.get(name, {}).get(key) != item for key, item in value.items()):
                stop('SAVED_STATE_CHANGED', '過去の実行記録が変化しました: '+name)
        elif after.get(name) != value:
            stop('SAVED_STATE_CHANGED', '既存の状態が変化しました: '+name)
    if progress['original_config'] is not None and load(private/'config.json') != progress['original_config']:
        stop('SAVED_STATE_CHANGED', '既存の接続設定が変化しました。')
    for name, expected in progress['protected_files'].items():
        path = private/name
        if not path.is_file() or sha(path.read_bytes()) != expected:
            stop('SAVED_STATE_CHANGED', '既存の保存ファイルが変化しました: '+name)


def verify_completed_study(value):
    study = value.get('study') or {}
    if (study.get('phase'), study.get('cursor'), study.get('stop'), study.get('code_hash')) != ('COMPLETE', 216, None, EVALUATION_HASH):
        stop('STUDY_INCOMPLETE', '完了した1.0.15の216件が必要です。追加実行はしていません。')
    cap=value.get('max_cost_usd');calls=value.get('session',{}).get('calls',-1);used=value.get('additional_decisions_used',-1)
    if value.get('additional_decisions_limit') != 251 or value.get('session_call_limit') != 509 or value.get('extra_retry_attempts') != {'limit':6,'used':6} or cap not in (20,100):
        stop('LIMIT_STATE_MISMATCH', '過去の上限・使用記録を確認できません。')
    if not (509 <= calls <= (549 if cap==100 else 509) and 251 <= used <= (275 if cap==100 else 251)):
        stop('LIMIT_STATE_MISMATCH', '既存使用量と今回の追加検証範囲が一致しません。')



def remote_snapshot(api):
    status = api.call('/recovery115')
    verify_completed_study(status)
    runs = {name: rid for name, rid in status['study'].get('runs', {}).items() if name.startswith('FORMAL-')}
    if len(runs) != 6:
        stop('STUDY_INCOMPLETE', '正式比較の6結果を確認できません。')
    exports, tasks, failed = {}, 0, 0
    for name, rid in sorted(runs.items()):
        value = api.call('/exports/'+rid)
        if value.get('run', {}).get('code_hash') != EVALUATION_HASH or not value.get('metrics', {}).get('complete'):
            stop('STUDY_INCOMPLETE', '保存済み結果の版・完了状態が一致しません。')
        value.pop('exported_at', None)  # Retrieval time only; evidence bytes remain represented.
        exports[name] = sha(value)
        tasks += len(value['tasks'])
        failed += sum(t['status'] == 'FAILED' for t in value['tasks'])
    if (tasks, failed) != (216, 4):
        stop('STUDY_INCOMPLETE', '216件・失敗4件の保存記録と一致しません。')
    status={k:v for k,v in status.items() if k!='max_cost_usd'}
    return {'status': status, 'export_hashes': exports, 'decisions': tasks, 'failed_decisions': failed}


def verify_health(health):
    allowed = {(v['version'], v['code_hash']) for v in DATA['baselines'].values()} | {(VERSION, DATA['new']['code_hash'])}
    if (health.get('package_version'), health.get('code_hash')) not in allowed or health.get('mode') != 'LIVE' or health.get('request_tier') != 'priority' or health.get('max_cost_usd') not in (20,100):
        stop('DEPLOY_MISMATCH', '現在の版・実行設定を確認できません。')


def verify_workflow(root):
    print('保存済みの資料レビューを使い、条件案の作成を1回確認します。', flush=True)
    environment = dict(os.environ); environment['PYTHONDONTWRITEBYTECODE'] = '1'
    result = subprocess.run([str(root/'.venv/bin/python'), str(root/'steps/prepare_workflow126.py')],
        cwd=root, env=environment, timeout=360)
    if result.returncode:
        stop('WORKFLOW_GATE_STOPPED', '条件案の確認で停止しました。上の保存結果を確認してください。自動再試行はしません。')


def main():
    parser = argparse.ArgumentParser()
    parser.add_argument('--deploy', action='store_true', help='Deploy the reviewed product update; no model calls or replay')
    parser.add_argument('--verify-workflow',action='store_true',help='After deployment, prepare one streamed workflow draft; no approval or case replay')
    parser.add_argument('--authorize-validation',action='store_true',help='Record the authorized one-time allowance: 40 calls, 24 judgments, USD 100 cumulative maximum')
    parser.add_argument('--reviewer',default='',help='Responsible person for the validation allowance')
    args = parser.parse_args()
    if args.authorize_validation and (not args.deploy or not args.reviewer.strip()):stop('REVIEWER_REQUIRED','追加検証の準備には --deploy と --reviewer 担当者名 が必要です。')
    if args.verify_workflow and not args.deploy:stop('DEPLOY_REQUIRED','条件案の確認には --deploy が必要です。')
    decoded = payload()
    root, private = Path.cwd().resolve(), Path.cwd().resolve()/'.jt'
    if not (private/'state.json').is_file():
        stop('STATE_MISSING', 'Judgment_Transfer_Runbook_v1.0 フォルダーで実行してください。')
    sys.dont_write_bytecode = True
    sys.path.insert(0, str(root))
    with (private/'runbook.lock').open('a') as lock:
        try:
            fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError:
            stop('RUNBOOK_BUSY', '別の処理が実行中です。')
        state = load(private/'state.json')
        if any(state['steps'].get(f'{n:02}', {}).get('status') != 'DONE' for n in range(9)):
            stop('STATE_MISMATCH', '00〜08完了済み環境を対象とします。')
        current = load(root/'package-manifest.json')
        backup = private/'upgrades'/VERSION
        checkpoint = backup/'install.json'
        progress = load(checkpoint) if checkpoint.exists() else None
        baseline = verify_package(root, current, progress)
        if shutil.disk_usage(root).free < 64*1024*1024:
            stop('DISK_SPACE', '空き64MiB未満です。既存記録は削除していません。')
        if progress:
            verify_local_records(root, progress)
        else:
            progress = {'payload_hash': sha(DATA), 'phase': 'PREPARED', 'from_version': baseline['version'], 'baseline_hash': sha(baseline),
                        'created_at': dt.datetime.now(dt.timezone.utc).isoformat(), 'original_state': state,
                        'original_config': load(private/'config.json') if (private/'config.json').is_file() else None,
                        'protected_files': local_snapshot(private)}
            for name in [*decoded, '.jt/state.json', '.jt/benchmark.json', '.jt/config.json']:
                path, destination = root/name, backup/'original'/name
                if path.is_file():
                    destination.parent.mkdir(parents=True, exist_ok=True)
                    shutil.copy2(path, destination)
                    destination.chmod(0o600)
            save(checkpoint, progress)
        from steps import runbook as r
        health = None
        if args.deploy:
            config = r.config()
            if config['project_id'] != PROJECT_ID:
                stop('PROJECT_MISMATCH', '既存の専用プロジェクト以外には反映しません。')
            os.environ['CLOUDSDK_BILLING_QUOTA_PROJECT'] = config['project_id']
            api = r.API()
            health = api.call('/health')
            verify_health(health)
            if progress['phase'] == 'DEPLOYED':
                # Deployment was already checked before the explicitly requested
                # source gate. Later legitimate model usage is not a redeploy.
                if health.get('code_hash') != DATA['new']['code_hash']:
                    stop('DEPLOY_MISMATCH', '適用済みアプリの版が一致しません。')
                current_remote = remote_snapshot(api)
                if current_remote['export_hashes'] != progress['remote_before']['export_hashes'] or current_remote['status']['study'] != progress['remote_before']['status']['study']:
                    stop('SAVED_STATE_CHANGED', '過去の比較記録が変化しました。')
                print('1.0.26の適用済み環境と過去の比較記録を確認しました。再デプロイはしません。', flush=True)
                if args.verify_workflow:
                    verify_workflow(root)
                return
            before = remote_snapshot(api)
            if 'remote_before' in progress and progress['remote_before'] != before:
                stop('SAVED_STATE_CHANGED', '更新開始後に完了結果または利用量が変化しました。')
            if 'remote_before' not in progress:
                progress['remote_before'] = before
                save(checkpoint, progress)
        for name in [n for n in decoded if n != 'package-manifest.json']+['package-manifest.json']:
            path = target(root, name)
            path.parent.mkdir(parents=True, exist_ok=True)
            temporary = path.with_name(path.name+'.upgrade-tmp')
            temporary.write_bytes(decoded[name])
            os.replace(temporary, path)
        import importlib
        importlib.reload(r)
        r.integrity()
        state = r.state()
        state['package_version'] = VERSION
        state.setdefault('upgrades', {}).setdefault(VERSION, {'from_version': progress['from_version'], 'installed_at': r.stamp(), 'code_hash': DATA['new']['code_hash'], 'deployed': False})
        r.save(r.STATE, state)
        progress['phase'] = 'INSTALLED'
        save(checkpoint, progress)
        verify_local_records(root, progress)
        print('1.0.26 適用済み。確認済みの更新を適用しました。', flush=True)
        if not args.deploy:
            print('ローカル適用のみ。モデル呼び出し・比較再実行は0回です。')
            return
        original_gc = r.gc
        def preserve_gc(*arguments, **options):
            if options.get('action') == '04-deploy':
                options['action'] = '04-deploy-'+VERSION
                revised = []
                for value in arguments:
                    if value == '--no-allow-unauthenticated':
                        continue
                    if value == '--invoker-iam-check':
                        value = '--no-invoker-iam-check'
                    if value.startswith('--set-env-vars='):
                        value = value.replace('JT_INPUT_USD_PER_MILLION=1.50', 'JT_INPUT_USD_PER_MILLION=2.70').replace('JT_OUTPUT_USD_PER_MILLION=9.00', 'JT_OUTPUT_USD_PER_MILLION=16.20')+',JT_REQUEST_TIER=priority'
                        value=value.replace('JT_MODEL_BUDGET_USD=20','JT_MODEL_BUDGET_USD=100')
                    revised.append(value)
                arguments = tuple(revised)
            return original_gc(*arguments, **options)
        r.gc = preserve_gc
        if health['code_hash'] != DATA['new']['code_hash']:
            print('公開設定・使用量を保持し、承認済みの累計100ドル上限でデプロイします。モデルは呼びません。', flush=True)
            r.step04()
        api = r.API()
        health = api.call('/health')
        verify_health(health)
        if health.get('package_version') != VERSION or health.get('code_hash') != DATA['new']['code_hash'] or health.get('max_cost_usd')!=100:
            stop('DEPLOY_MISMATCH', '1.0.26の反映を確認できません。')
        for name, expected in DATA['new']['files'].items():
            if not name.startswith('app/web/'):
                continue
            route = '/' if name == 'app/web/index.html' else '/assets/'+name.removeprefix('app/web/')
            request = urllib.request.Request(r.config()['url']+route, headers={'Cache-Control': 'no-cache'})
            with urllib.request.urlopen(request, timeout=30) as response:
                content = response.read()
            if sha(content) != expected:
                stop('ASSET_MISMATCH', '公開ファイル不一致: '+name)
        after = remote_snapshot(api)
        if progress['remote_before'] != after:
            stop('SAVED_STATE_CHANGED', '完了記録・承認・結果・利用量が変化しました。追加判断は実行していません。')
        verify_local_records(root, progress)
        state = r.state()
        state['upgrades'][VERSION].update(deployed=True, deployed_at=r.stamp())
        r.save(r.STATE, state)
        progress['phase'] = 'DEPLOYED'
        save(checkpoint, progress)
        report = {'version': VERSION, 'code_hash': DATA['new']['code_hash'], 'served_assets_verified': True,
                  'completed_study_budget_and_exports_unchanged': True, 'decisions_preserved': 216, 'failed_decisions_preserved': 4,
                  'model_calls': 0, 'formal_replays': 0, 'url': r.config()['url'], 'guided_demo_url': r.config()['url']+'/assets/demo/index.html'}
        report['cumulative_model_budget_usd']=100
        if args.authorize_validation:
            grant=api.call('/validation123/authorize',{'max_cost_usd':100,'reviewer_name':args.reviewer.strip(),'memo':'Authorized new document-based validation, preserving prior counters.'},key='release123-validation-authorization')
            r.save(root/'deliverables/release126/validation-allowance.json',grant)
            report['additional_validation_allowance']={'model_calls':40,'judgments':24,'retries':4}
        r.save(root/'deliverables/release126/deploy-verification.json', report)
        print('1.0.26 公開完了。画面の反映と、過去の検証記録・承認・利用量が変わっていないことを確認しました。')
        print('アプリURL: '+report['url'])
        print('説明用デモURL: '+report['guided_demo_url'])
        print('デプロイ処理のモデル呼び出し0回、比較再実行0回。')
        if args.verify_workflow:
            verify_workflow(root)


if __name__ == '__main__':
    try:
        main()
    except KeyboardInterrupt:
        sys.exit('中断しました。保存済み記録は残っています。同じコマンドで再開できます。')
    except Exception as error:
        if str(error).startswith('STOP '):
            sys.exit(str(error))
        if hasattr(error, 'code'):
            sys.exit('STOP '+str(error.code)+' / '+str(error))
        sys.exit('STOP RELEASE_ERROR / '+type(error).__name__+'。記録を削除せず確認してください。')
